import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// Schema Definition


export type ChartAnimationProps = Record<string, any>;

const ChartAnimation: React.FC<ChartAnimationProps> = ({
  backgroundColor = "#f3f0e6",
  transparentBackground = false,
  durationInSeconds = 8,
  
  titlePre = "Do you think ",
  titleHighlight = "motion graphics",
  titlePost = "improves your storytelling?",
  subhead = "Poll on @malloystudio IG 2027",
  
  highlightColor = "#fff200",
  bar1Color = "#e8a846",
  bar2Color = "#efdcb1",
  gridColor = "#b0b0b0",
  textColor = "#1a1a1a",
  
  bar1Value = 93,
  bar2Value = 7,
  bar1Label = "Favor",
  bar2Label = "Oppose",
}) => {
  // Load Fonts
  useFontLoader(["Playfair Display", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color Logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Animation Configs
  const titleDelay = 15;
  const subheadDelay = 30;
  const chartStartDelay = 45;
  const barGrowthDelay = 60;

  // --- Animations ---

  // 1. Title Entrance (Fade + Slide)
  const titleOpacity = interpolate(frame, [titleDelay, titleDelay + 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleTranslateY = interpolate(frame, [titleDelay, titleDelay + 20], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Highlight Reveal (Sweep)
  const highlightProgress = spring({
    frame: frame - titleDelay - 10,
    fps,
    config: { damping: 20, stiffness: 80 },
  });

  // 3. Subhead Fade
  const subheadOpacity = interpolate(frame, [subheadDelay, subheadDelay + 20], [0, 0.6], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 4. Grid Lines Expansion
  const gridProgress = interpolate(frame, [chartStartDelay, chartStartDelay + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: (t) => t * (2 - t), // easeOutQuad
  });

  // 5. Bars Growth (Spring)
  const bar1Progress = spring({
    frame: frame - barGrowthDelay,
    fps,
    config: { damping: 15, stiffness: 100, mass: 1 },
  });

  const bar2Progress = spring({
    frame: frame - barGrowthDelay - 10, // Slight stagger
    fps,
    config: { damping: 15, stiffness: 100, mass: 1 },
  });

  // 6. Axis Labels Fade
  const axisOpacity = interpolate(frame, [chartStartDelay + 10, chartStartDelay + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 7. Bar Value Fade
  const barValueOpacity = interpolate(frame, [barGrowthDelay + 20, barGrowthDelay + 40], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Styles ---
  
  // Layout Constants
  const contentPadding = width * 0.08;
  const chartHeight = height * 0.5;
  const chartBottom = height * 0.15;
  
  // Reserve space for Y-axis labels so they sit inside the content width
  const yAxisWidth = width * 0.12; 
  
  const titleFontSize = Math.min(width, height) * 0.06;
  const subheadFontSize = Math.min(width, height) * 0.025;
  const labelFontSize = Math.min(width, height) * 0.035;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* --- HEADER SECTION --- */}
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          left: contentPadding,
          right: contentPadding,
          opacity: titleOpacity,
          transform: `translateY(${titleTranslateY}px)`,
        }}
      >
        <h1
          style={{
            fontFamily: "Playfair Display",
            fontSize: titleFontSize,
            color: textColor,
            lineHeight: 1.2,
            margin: 0,
            marginBottom: 20,
          }}
        >
          {titlePre}
          <span style={{ position: "relative", whiteSpace: "pre-wrap", display: "inline-block" }}>
             {/* Highlight Background */}
            <div
              style={{
                position: "absolute",
                top: "0.1em",
                left: -5,
                right: -5,
                bottom: "0.05em",
                backgroundColor: highlightColor,
                zIndex: -1,
                transformOrigin: "left center",
                transform: `scaleX(${highlightProgress})`,
              }}
            />
            {titleHighlight}
          </span>
          {titlePost}
        </h1>
        
        <p
          style={{
            fontFamily: "Inter",
            fontSize: subheadFontSize,
            color: textColor,
            opacity: subheadOpacity,
            margin: 0,
            fontWeight: 400,
          }}
        >
          {subhead}
        </p>
      </div>

      {/* --- CHART SECTION --- */}
      <div
        style={{
          position: "absolute",
          bottom: chartBottom,
          left: contentPadding,
          right: contentPadding,
          height: chartHeight,
        }}
      >
        {/* Grid Lines: 0 to 100% */}
        {[0, 0.25, 0.5, 0.75, 1].map((step, i) => {
          const pct = Math.round(step * 100);
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                bottom: `${(step * 100)}%`,
                left: 0,
                width: "100%",
                height: 1,
                display: "flex",
                alignItems: "center",
              }}
            >
               {/* Y-Axis Label */}
              <span
                style={{
                  position: "absolute",
                  left: 0,
                  width: yAxisWidth,
                  fontFamily: "Inter",
                  fontSize: labelFontSize * 0.8,
                  color: textColor,
                  opacity: axisOpacity,
                  textAlign: "left",
                }}
              >
                {pct}%
              </span>
              
              {/* Grid Line */}
              <div
                style={{
                  position: "absolute",
                  left: yAxisWidth,
                  right: 0,
                  height: i === 0 ? 2 : 1, // Base line thicker
                  backgroundColor: i === 0 ? textColor : "transparent",
                  borderTop: i === 0 ? "none" : `2px dashed ${gridColor}`,
                  opacity: i === 0 ? 1 : 0.6,
                  transformOrigin: "left center",
                  transform: `scaleX(${gridProgress})`,
                }}
              />
            </div>
          );
        })}

        {/* Bars Container */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: yAxisWidth, 
            right: 0,
            height: "100%",
            display: "flex",
            justifyContent: "center", 
            alignItems: "flex-end", // Align container items to bottom
            gap: width * 0.1, 
          }}
        >
          
          {/* Bar 1: Favor */}
          <div style={{ 
            position: "relative",
            width: "35%",
            height: "100%", 
          }}>
            {/* Value Label */}
            <span
              style={{
                position: "absolute",
                width: "100%",
                bottom: `${bar1Value}%`, // Sits on top of the bar
                marginBottom: 10,
                fontFamily: "Inter",
                fontWeight: 700,
                fontSize: labelFontSize,
                color: textColor,
                opacity: barValueOpacity,
                textAlign: "center",
              }}
            >
              {bar1Value}%
            </span>

            {/* Bar Shape */}
            <div
              style={{
                position: "absolute",
                bottom: 0, // Anchored to the 0% grid line
                left: 0,
                width: "100%",
                height: `${bar1Value}%`,
                backgroundColor: bar1Color,
                transformOrigin: "bottom center",
                transform: `scaleY(${bar1Progress})`,
              }}
            />

            {/* Category Label */}
            <span
              style={{
                position: "absolute",
                top: "100%", // Below the chart area
                width: "100%",
                marginTop: 20,
                fontFamily: "Inter",
                fontWeight: 700,
                fontSize: labelFontSize,
                color: textColor,
                opacity: axisOpacity,
                textAlign: "center",
              }}
            >
              {bar1Label}
            </span>
          </div>

          {/* Bar 2: Oppose */}
          <div style={{ 
            position: "relative",
            width: "35%",
            height: "100%",
          }}>
             {/* Value Label */}
             <span
              style={{
                position: "absolute",
                width: "100%",
                bottom: `${bar2Value}%`, // Sits on top of the bar
                marginBottom: 10,
                fontFamily: "Inter",
                fontWeight: 700,
                fontSize: labelFontSize,
                color: textColor,
                opacity: barValueOpacity,
                textAlign: "center",
              }}
            >
              {bar2Value}%
            </span>

             {/* Bar Shape */}
             <div
              style={{
                position: "absolute",
                bottom: 0, // Anchored to the 0% grid line
                left: 0,
                width: "100%",
                height: `${bar2Value}%`,
                backgroundColor: bar2Color,
                transformOrigin: "bottom center",
                transform: `scaleY(${bar2Progress})`,
              }}
            />

            {/* Category Label */}
            <span
              style={{
                position: "absolute",
                top: "100%", // Below the chart area
                width: "100%",
                marginTop: 20,
                fontFamily: "Inter",
                fontWeight: 700,
                fontSize: labelFontSize,
                color: textColor,
                opacity: axisOpacity,
                textAlign: "center",
              }}
            >
              {bar2Label}
            </span>
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChartAnimation;